21	Address::InstanceConstSharedPtr findOrCheckFreePort(Address::InstanceConstSharedPtr addr_port,
22	                                                    Address::SocketType type) {
23	  if (addr_port == nullptr || addr_port->type() != Address::Type::Ip) {
24	    ADD_FAILURE() << "Not an internet address: "
25	                  << (addr_port == nullptr ? "nullptr" : addr_port->asString());
26	    return nullptr;
27	  }
28	  IoHandlePtr io_handle = addr_port->socket(type);
29	  // Not setting REUSEADDR, therefore if the address has been recently used we won't reuse it here.
30	  // However, because we're going to use the address while checking if it is available, we'll need
31	  // to set REUSEADDR on listener sockets created by tests using an address validated by this means.
32	  Api::SysCallIntResult result = addr_port->bind(io_handle->fd());
33	  int err;
34	  const char* failing_fn = nullptr;
35	  if (result.rc_ != 0) {
36	    err = result.errno_;
37	    failing_fn = "bind";
38	  } else if (type == Address::SocketType::Stream) {
39	    // Try listening on the port also, if the type is TCP.
40	    if (::listen(io_handle->fd(), 1) != 0) {
41	      err = errno;
42	      failing_fn = "listen";
43	    }
44	  }
45	  if (failing_fn != nullptr) {
46	    if (err == EADDRINUSE) {
47	      // The port is already in use. Perfectly normal.
48	      return nullptr;
49	    } else if (err == EACCES) {
50	      // A privileged port, and we don't have privileges. Might want to log this.
51	      return nullptr;
52	    }
53	    // Unexpected failure.
54	    ADD_FAILURE() << failing_fn << " failed for '" << addr_port->asString()
55	                  << "' with error: " << strerror(err) << " (" << err << ")";
56	    return nullptr;
57	  }
58	  // If the port we bind is zero, then the OS will pick a free port for us (assuming there are
59	  // any), and we need to find out the port number that the OS picked so we can return it.
60	  if (addr_port->ip()->port() == 0) {
61	    return Address::addressFromFd(io_handle->fd());
62	  }
63	  return addr_port;
64	}
