133	Address::InstanceConstSharedPtr getAnyAddress(const Address::IpVersion version, bool v4_compat) {
134	  if (version == Address::IpVersion::v4) {
135	    return Network::Utility::getIpv4AnyAddress();
136	  }
137	  if (v4_compat) {
138	    // This will return an IPv6 ANY address ("[::]:0") like the getIpv6AnyAddress() below, but
139	    // with the internal 'v6only' member set to false. This will allow a socket created from this
140	    // address to accept IPv4 connections. IPv4 connections received on IPv6 sockets will have
141	    // Ipv4-mapped IPv6 addresses, which we will then internally interpret as IPv4 addresses so
142	    // that, for example, access logging will show IPv4 address format for IPv4 connections even
143	    // if they were received on an IPv6 socket.
144	    static Address::InstanceConstSharedPtr any(new Address::Ipv6Instance(sockaddrIn6Any(), false));
145	    return any;
146	  }
147	  return Network::Utility::getIpv6AnyAddress();
148	}
