123	TEST_P(UdpProxyIntegrationTest, HelloWorldOnLoopback) {
124	  setup(1);
125	  const uint32_t port = lookupPort("listener_0");
126	  const auto listener_address = Network::Utility::resolveUrl(
127	      fmt::format("tcp://{}:{}", Network::Test::getLoopbackAddressUrlString(version_), port));
128	  requestResponseWithListenerAddress(*listener_address);
